// On essaie de lancer un million de threads PLATEFORME classiques.
public class TropDeThreads {
    public static void main(String[] args) throws InterruptedException {
        for (int i = 0; i < 1_000_000; i++) {
            // Chaque thread plateforme réserve ~1 Mo de pile.
            Thread t = new Thread(() -> {
                try {
                    Thread.sleep(1000); // simule une attente (I/O, réseau...)
                } catch (InterruptedException e) { }
            });
            t.start();
        }
        // En pratique : la JVM s'épuise bien AVANT le million.
        // Typiquement OutOfMemoryError: unable to create native thread.
    }
}

public class CreerVirtuels {
    public static void main(String[] args) throws InterruptedException {
        // Façon 1 : le builder, ici on en profite pour nommer le thread.
        Thread t1 = Thread.ofVirtual()
                          .name("salutation")
                          .start(() -> System.out.println("Bonjour depuis " + Thread.currentThread()));

        // Façon 2 : le raccourci en une ligne.
        Thread t2 = Thread.startVirtualThread(() -> System.out.println("Salut !"));

        // join() attend la fin d'un thread (sinon main peut se terminer avant).
        t1.join();
        t2.join();

        // Vérifier qu'un thread est virtuel :
        System.out.println(t2.isVirtual()); // true
    }
}

import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class ViaExecutor {
    public static void main(String[] args) {
        // Cet executor crée UN thread virtuel NEUF par tâche soumise.
        // try-with-resources : close() attend la fin de toutes les tâches.
        try (ExecutorService executor = Executors.newVirtualThreadPerTaskExecutor()) {
            for (int i = 0; i < 10_000; i++) {
                int numero = i;
                executor.submit(() -> {
                    // Code BLOQUANT tout simple : on "dort" 1 seconde.
                    Thread.sleep(java.time.Duration.ofSeconds(1));
                    return numero;
                });
            }
        } // ici, close() attend que les 10 000 tâches soient finies
        System.out.println("Les 10 000 tâches sont terminées.");
    }
}

