import java.time.Duration;
import java.util.concurrent.Executors;

public class Cent {
    public static void main(String[] args) {
        try (var executor = Executors.newVirtualThreadPerTaskExecutor()) {
            for (int i = 0; i < 100; i++) {
                int n = i;
                executor.submit(() -> {
                    System.out.println("Tache " + n + " demarre");
                    Thread.sleep(Duration.ofMillis(500));
                    System.out.println("Tache " + n + " finie");
                    return null;
                });
            }
        } // close() attend la fin des 100 taches
        System.out.println("Tout est fini.");
    }
}

Les 100 threads virtuels attendent en même temps : l'ensemble prend environ 500 ms, pas 100 fois 500 ms.

