import java.util.concurrent.Executors;
import java.util.List;

public class AppelsEnParallele {

    // Simule un appel réseau lent (I/O) : on attend 300 ms puis on répond.
    static String recupererProfil(int userId) throws InterruptedException {
        Thread.sleep(300); // le thread virtuel se DÉMONTE ici, le porteur est libre
        return "profil-" + userId;
    }

    public static void main(String[] args) throws Exception {
        var ids = List.of(1, 2, 3, 4, 5);
        try (var executor = Executors.newVirtualThreadPerTaskExecutor()) {
            // Les 5 appels partent en même temps, chacun sur son thread virtuel.
            var futures = ids.stream()
                             .map(id -> executor.submit(() -> recupererProfil(id)))
                             .toList();
            for (var f : futures) {
                System.out.println(f.get()); // récupère le résultat de chaque appel
            }
        }
        // Total : ~300 ms (en parallèle), pas 5 x 300 ms.
    }
}

import java.util.concurrent.locks.ReentrantLock;

public class EviterLePinning {

    private final Object verrou = new Object();
    private final ReentrantLock lock = new ReentrantLock();

    // MAUVAIS : blocage (I/O) DANS un synchronized -> épingle le porteur.
    void risqueDePinning() throws InterruptedException {
        synchronized (verrou) {
            Thread.sleep(1000); // attente bloquante tant qu'on tient le moniteur
        }
    }

    // BON : un ReentrantLock n'épingle pas le porteur pendant l'attente.
    void sansPinning() throws InterruptedException {
        lock.lock();
        try {
            Thread.sleep(1000); // ici le thread virtuel peut se démonter
        } finally {
            lock.unlock();
        }
    }
}

import java.io.*;
import java.net.ServerSocket;
import java.net.Socket;
import java.util.concurrent.Executors;

public class ServeurEcho {
    public static void main(String[] args) throws IOException {
        // Un thread virtuel NEUF par connexion acceptée.
        try (var executor = Executors.newVirtualThreadPerTaskExecutor();
             var serveur = new ServerSocket(8080)) {
            System.out.println("En écoute sur le port 8080...");
            while (true) {
                Socket client = serveur.accept(); // attend une connexion (bloquant)
                // Chaque client est traité sur SON propre thread virtuel.
                executor.submit(() -> traiter(client));
            }
        }
    }

    // Code BLOQUANT tout simple, lisible ligne par ligne.
    static void traiter(Socket client) {
        try (client;
             var in = new BufferedReader(new InputStreamReader(client.getInputStream()));
             var out = new PrintWriter(client.getOutputStream(), true)) {
            String ligne;
            while ((ligne = in.readLine()) != null) { // attente réseau = démontage
                out.println("echo: " + ligne);
            }
        } catch (IOException e) {
            System.err.println("Erreur client : " + e.getMessage());
        }
    }
}
